"""GTM-114: «About RosmarOps» served from the repository. The three pages in site/_static/ are generated by
observatory/build.py from wp/pages/*.html, and wp/htaccess-static.txt maps their WordPress addresses to them.

Run from the repository root:  python3 -m unittest wp/tests/test_static_about.py
"""

import re
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "observatory"))
import agent_lists  # noqa: E402

PAGES = {"en": ("about-en.html", "/blog/about/"), "es": ("about-es.html", "/es/blog/que-es-rosmarops/"),
         "ca": ("about-ca.html", "/ca/blog/que-es-rosmarops/")}


class StaticAbout(unittest.TestCase):
    def test_pages(self):
        agents = agent_lists.load_agents()
        for lang, (name, path) in PAGES.items():
            t = (ROOT / "site" / "_static" / name).read_text(encoding="utf-8")
            self.assertIn(f'<html lang="{lang}">', t)
            self.assertIn(f'<link rel="canonical" href="https://rosmarops.com{path}">', t)
            for other, (_, p) in PAGES.items():
                self.assertIn(f'<link rel="alternate" hreflang="{other}" href="https://rosmarops.com{p}">', t)
            self.assertIn('hreflang="x-default" href="https://rosmarops.com/blog/about/"', t)
            self.assertNotIn("<!-- wp:", t)
            self.assertNotIn("wp-block-", t)
            self.assertIn("/assets/visits/visits.js", t)
            scored = agent_lists.join(agent_lists.names(agents, "scored", lang), lang)
            self.assertIn(scored, t.replace("&amp;", "&"), lang)  # the lists are the current generated ones

    def test_htaccess_block(self):
        t = (ROOT / "wp" / "htaccess-static.txt").read_text(encoding="utf-8")
        self.assertTrue(t.startswith("# BEGIN RosmarOps STATIC"))
        self.assertTrue(t.rstrip().endswith("# END RosmarOps STATIC"))
        rules = re.findall(r"^RewriteRule \^(\S+)\$ _static/(\S+) \[END\]$", t, re.M)
        self.assertEqual(sorted(rules), sorted((p.lstrip("/"), n) for n, p in PAGES.values()))
        self.assertIn("RewriteRule ^_static/ - [R=404,L]", t)
        # each mapped rule is skipped on plain http (left to the HTTPS block)
        self.assertEqual(t.count("RewriteCond %{SERVER_PORT} !^80$ [OR]"), 3)


if __name__ == "__main__":
    unittest.main()
